120	    name: &str,
121	    args: Vec<DenseArray>,
122	    f: fn(f64, f64) -> f64,
123	) -> Result<DenseArray, RuntimeError> {
124	    if args.len() != 2 {
125	        return Err(RuntimeError::ArityMismatch {
126	            func: name.into(),
