196	/// `concat(a, b)` and `last_row(matrix)` -- array utilities for
197	/// generation loops. `concat` joins two rank-0/1 arrays into a 1-D
198	/// vector; `last_row` extracts the final row of a rank-2 matrix.
199	fn array_util(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
200	    if name == "concat" {
201	        if args.len() != 2 {
202	            return Err(RuntimeError::ArityMismatch {
203	                func: name.into(),
204	                expected: 2,
205	                got: args.len(),
206	            });
207	        }
208	        for (i, a) in args.iter().enumerate() {
209	            if a.rank() > 1 {
210	                return Err(RuntimeError::InvalidArgument {
211	                    func: name.into(),
212	                    reason: format!("argument {i} must be rank 0 or 1, got rank {}", a.rank()),
213	                });
214	            }
215	        }
216	        let mut data = Vec::with_capacity(args[0].data().len() + args[1].data().len());
217	        data.extend_from_slice(args[0].data());
218	        data.extend_from_slice(args[1].data());
219	        Ok(DenseArray::from_vec(data))
220	    } else {
221	        // last_row
222	        if args.len() != 1 {
223	            return Err(RuntimeError::ArityMismatch {
224	                func: name.into(),
225	                expected: 1,
226	                got: args.len(),
227	            });
228	        }
229	        if args[0].rank() != 2 {
230	            return Err(RuntimeError::InvalidArgument {
231	                func: name.into(),
232	                reason: format!("expected rank-2 matrix, got rank {}", args[0].rank()),
233	            });
234	        }
235	        let cols = args[0].shape().dims()[1];
236	        let data = args[0].data();
237	        Ok(DenseArray::from_vec(data[data.len() - cols..].to_vec()))
238	    }
239	}
