1	//! Lexer for MLPL source code.
2	
3	use mlpl_core::Span;
4	
5	use crate::error::ParseError;
6	use crate::lex_util::{
7	    lex_builtin_ref, lex_number, lex_string, single_char_token, skip_whitespace,
8	};
9	use crate::token::{Token, TokenKind};
10	
11	/// Tokenize MLPL source code.
12	pub fn lex(source: &str) -> Result<Vec<Token>, ParseError> {
13	    let mut lexer = Lexer::new(source);
14	    let mut tokens = Vec::new();
15	    loop {
16	        let tok = lexer.next_token()?;
17	        let done = tok.kind == TokenKind::Eof;
18	        tokens.push(tok);
19	        if done {
20	            break;
21	        }
22	    }
23	    Ok(tokens)
24	}
25	
26	struct Lexer<'a> {
27	    bytes: &'a [u8],
28	    source: &'a str,
29	    pos: usize,
30	    prev_was_value: bool,
31	}
32	
33	impl<'a> Lexer<'a> {
34	    fn new(source: &'a str) -> Self {
35	        Self {
36	            bytes: source.as_bytes(),
37	            source,
38	            pos: 0,
39	            prev_was_value: false,
40	        }
41	    }
42	
43	    fn make_tok(&mut self, kind: TokenKind, end: usize, prev_was_value: bool) -> Token {
44	        let span = Span::new(self.pos, end);
45	        self.pos = end;
46	        self.prev_was_value = prev_was_value;
47	        Token { kind, span }
48	    }
49	
50	    fn next_token(&mut self) -> Result<Token, ParseError> {
51	        self.pos = skip_whitespace(self.bytes, self.pos);
52	        if self.pos >= self.bytes.len() {
53	            return Ok(self.make_tok(TokenKind::Eof, self.pos, false));
54	        }
55	        let b = self.bytes[self.pos];
56	        if b == b'\n' {
57	            return Ok(self.make_tok(TokenKind::Newline, self.pos + 1, false));
58	        }
59	        if let Some((kind, end)) = lex_builtin_ref(self.bytes, self.pos) {
60	            return Ok(self.make_tok(kind, end, true));
61	        }
62	        if let Some(kind) = single_char_token(b) {
63	            let is_val = matches!(kind, TokenKind::RParen | TokenKind::RBracket);
64	            return Ok(self.make_tok(kind, self.pos + 1, is_val));
65	        }
66	        if b == b'"' {
67	            let (kind, end) = lex_string(self.bytes, self.pos)?;
68	            return Ok(self.make_tok(kind, end, true));
69	        }
70	        if b == b'-' {
71	            return self.lex_minus();
72	        }
73	        if b.is_ascii_digit() {
74	            return self.lex_digit();
75	        }
76	        if b.is_ascii_alphabetic() || b == b'_' {
77	            return Ok(self.lex_ident());
78	        }
79	        let ch = self.source[self.pos..].chars().next().unwrap();
80	        Err(ParseError::UnexpectedCharacter {
81	            ch,
82	            span: Span::new(self.pos, self.pos + ch.len_utf8()),
83	        })
84	    }
85	
86	    fn lex_minus(&mut self) -> Result<Token, ParseError> {
87	        if let Some((tok, end)) = lex_number(self.bytes, self.pos).filter(|_| !self.prev_was_value)
88	        {
89	            let span = Span::new(self.pos, end);
90	            self.pos = end;
91	            self.prev_was_value = true;
92	            return Ok(Token { kind: tok, span });
93	        }
94	        let tok = Token {
95	            kind: TokenKind::Minus,
96	            span: Span::new(self.pos, self.pos + 1),
97	        };
98	        self.pos += 1;
99	        self.prev_was_value = false;
100	        Ok(tok)
101	    }
102	
103	    fn lex_digit(&mut self) -> Result<Token, ParseError> {
104	        if let Some((tok, end)) = lex_number(self.bytes, self.pos) {
105	            let span = Span::new(self.pos, end);
106	            self.pos = end;
107	            self.prev_was_value = true;
108	            return Ok(Token { kind: tok, span });
109	        }
110	        Err(ParseError::InvalidNumber {
111	            span: Span::new(self.pos, self.pos + 1),
112	        })
113	    }
114	
115	    fn lex_ident(&mut self) -> Token {
116	        let start = self.pos;
117	        while self.pos < self.bytes.len()
118	            && (self.bytes[self.pos].is_ascii_alphanumeric() || self.bytes[self.pos] == b'_')
119	        {
120	            self.pos += 1;
121	        }
122	        let name = std::str::from_utf8(&self.bytes[start..self.pos])
123	            .unwrap()
124	            .to_owned();
125	        let kind = match name.as_str() {
126	            "repeat" => TokenKind::Repeat,
127	            "train" => TokenKind::Train,
128	            "for" => TokenKind::For,
129	            "in" => TokenKind::In,
130	            "experiment" => TokenKind::Experiment,
131	            "device" => TokenKind::Device,
132	            "if" => TokenKind::If,
133	            "else" => TokenKind::Else,
134	            "while" => TokenKind::While,
135	            "break" => TokenKind::Break,
136	            "continue" => TokenKind::Continue,
137	            "def" => TokenKind::Def,
