    b: usize,
    c_in: usize,
    h: usize,
    w: usize,
    c_out: usize,
    kh: usize,
    kw: usize,
    stride: usize,
    padding: usize,
    h_out: usize,
    w_out: usize,
}

pub(crate) fn run(args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    if args.len() != 4 {
        return Err(RuntimeError::ArityMismatch {
            func: "conv2d".into(),
            expected: 4,
            got: args.len(),
        });
    }
    let p = validate(&args)?;
    let out = compute(args[0].data(), args[1].data(), &p);
    Ok(DenseArray::new(
        Shape::new(vec![p.b, p.c_out, p.h_out, p.w_out]),
        out,
    )?)
}

fn validate(args: &[DenseArray]) -> Result<Params, RuntimeError> {
    let stride = args[2].data()[0] as usize;
    let padding = args[3].data()[0] as usize;
    let id = args[0].shape().dims();
    let fd = args[1].shape().dims();
    if id.len() != 4 || fd.len() != 4 {
        return Err(RuntimeError::InvalidArgument {
            func: "conv2d".into(),
            reason: format!(
                "input must be [B,C_in,H,W] and filters \
                 [C_out,C_in,kH,kW], got ranks {} and {}",
                id.len(),
                fd.len()
            ),
        });
    }
    if id[1] != fd[1] {
        return Err(RuntimeError::InvalidArgument {
            func: "conv2d".into(),
            reason: format!(
                "input channels {} != filter channels {}",
                id[1], fd[1]
            ),
        });
    }
    Ok(Params {
        b: id[0],
        c_in: id[1],
        h: id[2],
        w: id[3],
        c_out: fd[0],
        kh: fd[2],
        kw: fd[3],
        stride,
        padding,
        h_out: (id[2] + 2 * padding - fd[2]) / stride + 1,
        w_out: (id[3] + 2 * padding - fd[3]) / stride + 1,
    })
}

fn compute(idata: &[f64], fdata: &[f64], p: &Params) -> Vec<f64> {
    let mut out = vec![0.0f64; p.b * p.c_out * p.h_out * p.w_out];
    for bi in 0..p.b {
        for co in 0..p.c_out {
            for oh in 0..p.h_out {
                for ow in 0..p.w_out {
                    out[bi * p.c_out * p.h_out * p.w_out
                        + co * p.h_out * p.w_out
                        + oh * p.w_out
                        + ow] = conv_pixel(idata, fdata, p, bi, co, oh, ow);
                }
            }
        }
    }
    out
}

fn conv_pixel(
    idata: &[f64],
    fdata: &[f64],
    p: &Params,
    bi: usize,
    co: usize,
    oh: usize,
    ow: usize,
) -> f64 {
    let mut sum = 0.0;
    for ci in 0..p.c_in {
        for fh in 0..p.kh {
            for fw in 0..p.kw {
                let ih = (oh * p.stride + fh) as isize - p.padding as isize;
                let iw = (ow * p.stride + fw) as isize - p.padding as isize;
                if ih >= 0
                    && ih < p.h as isize
                    && iw >= 0
                    && iw < p.w as isize
                {
                    let iv = idata[bi * p.c_in * p.h * p.w
                        + ci * p.h * p.w
                        + ih as usize * p.w
                        + iw as usize];
                    let fv = fdata[co * p.c_in * p.kh * p.kw
                        + ci * p.kh * p.kw
                        + fh * p.kw
                        + fw];
                    sum += iv * fv;
                }
            }
        }
    }
    sum
}

