                + ci * p.h * p.w
                + (oh * p.ph + fh) * p.w
                + ow * p.pw
                + fw];
            if p.is_max {
                val = val.max(v);
            } else {
                val += v;
            }
        }
    }
    if !p.is_max {
        val /= (p.ph * p.pw) as f64;
    }
    val
}

