36	/// `cross_entropy(logits, targets)` fused log-softmax + NLL, scalar mean.
37	///
38	/// Logits are `[N, V]` or `[B, T, V]` float; targets are `[N]` or
39	/// `[B, T]` integer-valued (represented as f64 with whole-number
40	/// values, the convention MLPL uses for all integer-typed builtins).
41	/// Errors surface as `InvalidArgument` with the reason string; the
42	/// `mlpl-eval` layer maps them to `EvalError::ShapeMismatch` where
43	/// appropriate.
44	fn builtin_cross_entropy(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
45	    if args.len() != 2 {
46	        return Err(RuntimeError::ArityMismatch {
47	            func: name.into(),
48	            expected: 2,
49	            got: args.len(),
50	        });
51	    }
52	    let (n, v, idx) = cross_entropy_indices(name, &args[0], &args[1])?;
53	    let data = args[0].data();
54	    let mut total = 0.0;
55	    for (i, &t) in idx.iter().enumerate() {
56	        let row = &data[i * v..(i + 1) * v];
57	        let m = row.iter().copied().fold(f64::NEG_INFINITY, f64::max);
58	        let lse: f64 = m + row.iter().map(|x| (x - m).exp()).sum::<f64>().ln();
59	        total += lse - row[t];
60	    }
61	    Ok(DenseArray::from_scalar(total / n as f64))
62	}
63	
64	/// Validate logits / targets shapes and convert targets into a flat
65	/// `Vec<usize>`. Returns `(N, V, indices)` on success.
66	fn cross_entropy_indices(
67	    name: &str,
68	    logits: &DenseArray,
69	    targets: &DenseArray,
70	) -> Result<(usize, usize, Vec<usize>), RuntimeError> {
71	    let dims = logits.shape().dims();
72	    let (n, v) = match dims.len() {
73	        2 => (dims[0], dims[1]),
74	        3 => (dims[0] * dims[1], dims[2]),
75	        r => {
76	            return Err(RuntimeError::InvalidArgument {
77	                func: name.into(),
78	                reason: format!("logits must be rank 2 or 3, got rank {r}"),
79	            });
80	        }
81	    };
82	    if targets.elem_count() != n {
83	        return Err(RuntimeError::InvalidArgument {
84	            func: name.into(),
85	            reason: format!(
86	                "targets must have {n} elements to match logits rows, got {}",
87	                targets.elem_count()
88	            ),
89	        });
90	    }
91	    let mut idx = Vec::with_capacity(n);
92	    for (i, &t) in targets.data().iter().enumerate() {
93	        if t < 0.0 || t.fract() != 0.0 {
94	            return Err(RuntimeError::InvalidArgument {
95	                func: name.into(),
96	                reason: format!("target[{i}] must be a non-negative integer, got {t}"),
97	            });
98	        }
99	        let ti = t as usize;
100	        if ti >= v {
101	            return Err(RuntimeError::InvalidArgument {
102	                func: name.into(),
103	                reason: format!("target[{i}] = {ti} out of range for V = {v}"),
104	            });
105	        }
106	        idx.push(ti);
107	    }
108	    Ok((n, v, idx))
109	}
110	
111	/// Standard transformer sinusoidal positional encoding table.
112	///
113	/// `sinusoidal_encoding(seq_len, d_model)` returns a deterministic
114	/// `[seq_len, d_model]` table labeled `[time, dim]`:
115	///
116	/// - even cols `2i`:   `sin(pos / 10000^(2i / d_model))`
117	/// - odd cols `2i+1`:  `cos(pos / 10000^(2i / d_model))`
118	///
119	/// Pure -- no params, no seed. The `[time, dim]` labels propagate
120	/// through element-wise add when paired with a token embedding
121	/// output of matching shape.
122	fn builtin_sinusoidal_encoding(
123	    name: &str,
124	    args: Vec<DenseArray>,
125	) -> Result<DenseArray, RuntimeError> {
126	    let (t, d) = parse_sinusoidal_args(name, &args)?;
127	    let mut data = vec![0.0_f64; t * d];
128	    for pos in 0..t {
129	        for col in 0..d {
130	            let exponent = (2 * (col / 2)) as f64 / d as f64;
131	            let theta = pos as f64 / 10000.0_f64.powf(exponent);
132	            data[pos * d + col] = if col % 2 == 0 {
133	                theta.sin()
134	            } else {
135	                theta.cos()
136	            };
137	        }
138	    }
139	    let arr = DenseArray::new(Shape::new(vec![t, d]), data)?;
140	    Ok(arr.with_labels(vec![Some("time".into()), Some("dim".into())])?)
141	}
142	
143	fn parse_sinusoidal_args(name: &str, args: &[DenseArray]) -> Result<(usize, usize), RuntimeError> {
144	    if args.len() != 2 {
145	        return Err(RuntimeError::ArityMismatch {
146	            func: name.into(),
147	            expected: 2,
148	            got: args.len(),
149	        });
150	    }
151	    for (i, a) in args.iter().enumerate() {
152	        if a.rank() != 0 {
153	            return Err(RuntimeError::InvalidArgument {
154	                func: name.into(),
155	                reason: format!("argument {i} must be a scalar, got rank {}", a.rank()),
156	            });
157	        }
158	    }
159	    let seq_len = args[0].data()[0];
160	    let d_model = args[1].data()[0];
161	    if seq_len < 0.0 || seq_len.fract() != 0.0 {
162	        return Err(RuntimeError::InvalidArgument {
163	            func: name.into(),
164	            reason: format!("seq_len must be a non-negative integer, got {seq_len}"),
165	        });
166	    }
167	    if d_model <= 0.0 || d_model.fract() != 0.0 {
168	        return Err(RuntimeError::InvalidArgument {
169	            func: name.into(),
170	            reason: format!("d_model must be a positive integer, got {d_model}"),
171	        });
172	    }
173	    Ok((seq_len as usize, d_model as usize))
174	}
175	
176	/// Map a flat element index to its softmax group index --
177	/// the same flat index with the `axis` coordinate stripped
178	/// out, so every position along `axis` shares one group.
179	fn softmax_group_index(flat: usize, axis_size: usize, axis_stride: usize) -> usize {
180	    if axis_stride > 1 {
181	        let outer = flat / (axis_size * axis_stride);
182	        let inner = flat % axis_stride;
183	        outer * axis_stride + inner
184	    } else {
185	        flat / axis_size
186	    }
187	}
188	
189	fn builtin_softmax(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
190	    if args.len() != 2 {
191	        return Err(RuntimeError::ArityMismatch {
192	            func: name.into(),
193	            expected: 2,
194	            got: args.len(),
195	        });
196	    }
197	    if args[1].rank() != 0 {
198	        return Err(RuntimeError::InvalidArgument {
199	            func: name.into(),
200	            reason: format!("axis must be scalar, got rank {}", args[1].rank()),
201	        });
202	    }
203	    let a = &args[0];
204	    let axis = args[1].data()[0] as usize;
205	    let dims = a.shape().dims().to_vec();
206	    if axis >= dims.len() {
207	        return Err(RuntimeError::InvalidArgument {
208	            func: name.into(),
209	            reason: format!("axis {axis} out of range for rank {}", dims.len()),
210	        });
211	    }
212	    let axis_size = dims[axis];
213	    // Stride along `axis` = product of trailing dims (1 if axis is last).
214	    let axis_stride: usize = dims[axis + 1..].iter().product();
215	    let group_count = (a.elem_count() / axis_size).max(1);
216	    let mut maxv = vec![f64::NEG_INFINITY; group_count];
217	    for flat in 0..a.elem_count() {
218	        let g = softmax_group_index(flat, axis_size, axis_stride);
219	        let v = a.data()[flat];
220	        if v > maxv[g] {
221	            maxv[g] = v;
222	        }
223	    }
224	    let mut out = vec![0.0f64; a.elem_count()];
225	    let mut sums = vec![0.0f64; group_count];
226	    for (flat, slot) in out.iter_mut().enumerate() {
227	        let g = softmax_group_index(flat, axis_size, axis_stride);
228	        let e = (a.data()[flat] - maxv[g]).exp();
229	        *slot = e;
230	        sums[g] += e;
231	    }
232	    for (flat, slot) in out.iter_mut().enumerate() {
233	        let g = softmax_group_index(flat, axis_size, axis_stride);
234	        *slot /= sums[g];
235	    }
236	    Ok(DenseArray::new(Shape::new(dims), out)?)
237	}
238	
239	fn builtin_one_hot(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
240	    if args.len() != 2 {
241	        return Err(RuntimeError::ArityMismatch {
242	            func: name.into(),
243	            expected: 2,
244	            got: args.len(),
245	        });
246	    }
247	    if args[0].rank() != 1 {
248	        return Err(RuntimeError::InvalidArgument {
249	            func: name.into(),
250	            reason: format!("labels must be a vector, got rank {}", args[0].rank()),
251	        });
252	    }
253	    if args[1].rank() != 0 {
254	        return Err(RuntimeError::InvalidArgument {
255	            func: name.into(),
256	            reason: "k must be a scalar".into(),
257	        });
258	    }
259	    let labels = args[0].data();
260	    let k = args[1].data()[0] as usize;
261	    let n = labels.len();
262	    let mut data = vec![0.0f64; n * k];
263	    for (i, &lab) in labels.iter().enumerate() {
264	        let j = lab as usize;
265	        if j >= k {
266	            return Err(RuntimeError::InvalidArgument {
267	                func: name.into(),
268	                reason: format!("label {j} out of range for k = {k}"),
269	            });
270	        }
271	        data[i * k + j] = 1.0;
272	    }
273	    Ok(DenseArray::new(Shape::new(vec![n, k]), data)?)
274	}
