114	    /// per-head outputs along the column axis) and the rank-3
115	    /// batched attention path (stack per-batch outputs along the
116	    /// batch axis) to replace the previous O(N^2) binary-concat
117	    /// chain with a single O(N) op.
118	    pub fn stack(arrays: &[&DenseArray], axis: usize) -> Result<DenseArray, ArrayError> {
119	        if arrays.is_empty() {
120	            return Err(ArrayError::ShapeMismatch {
121	                source: 0,
122	                target: 1,
123	            });
124	        }
125	        let first = arrays[0];
126	        let dims = first.shape().dims();
127	        if axis >= dims.len() {
