        return Err(ArrayError::ShapeMismatch {
            source: dims.len(),
            target: 4,
        });
    }
    let (b, c, h, w) = (dims[0], dims[1], dims[2], dims[3]);
    if patch_size == 0 || h % patch_size != 0 || w % patch_size != 0 {
